'use strict';
(()=>{
 let key='',dashboard,lastActivity=Date.now();const status=document.querySelector('#operator-status'),desk=document.querySelector('#operator-desk'),login=document.querySelector('#operator-login');
 const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 async function api(path,data){const response=await fetch('/api/admin/'+path,{method:data?'POST':'GET',headers:{Authorization:'Bearer '+key,...(data?{'Content-Type':'application/json'}:{})},...(data?{body:JSON.stringify(data)}:{}),cache:'no-store'});const result=await response.json();if(!response.ok)throw Error(result.error||'Request failed.');return result;}
 function lock(){key='';dashboard=null;desk.hidden=true;login.hidden=false;login.reset();document.querySelector('#offer-form').reset();document.querySelectorAll('#operator-offers,#operator-reports,#operator-audit').forEach(el=>el.replaceChildren());status.textContent='Desk locked.';}
 async function refresh(){dashboard=await api('dashboard');const counts=dashboard.subscriberCounts;document.querySelector('#desk-summary').textContent=`${dashboard.offers.length} offers · ${dashboard.reports.filter(r=>['new','reviewing'].includes(r.status)).length} open reports · ${counts.active} confirmed subscribers`;
 document.querySelector('#operator-offers').innerHTML=dashboard.offers.map(o=>`<article class="desk-record"><h3>${esc(o.title)}</h3><span class="data">${esc(o.id)} · ${esc(o.status)} · revision ${o.revision}</span><p>${esc(o.conditions)}</p><p>Last check: ${esc(o.checked_at||'None')} · Expiry: ${esc(o.expires_at)}</p><div class="desk-actions"><button data-edit="${esc(o.id)}">edit.draft_</button><button data-publish="${esc(o.id)}">publish.fluq_</button><button data-pause="${esc(o.id)}">pause.fluq_</button><button data-patch="${esc(o.id)}">mark.patched_</button></div><details><summary>Record a check</summary><form class="alert-form check-form" data-offer="${esc(o.id)}"><label>Result<select name="result"><option value="working">Working</option><option value="failed">Failed / patched</option></select></label><label>Method<select name="method"><option value="checkout">Checked in the checkout</option><option value="merchant">Confirmed on the merchant’s page</option></select></label><label>Source URL<input name="source_url" type="url" pattern="https://.*" required></label><label>What you checked<textarea name="evidence" required minlength="15" maxlength="2500" placeholder="Date, item, basket, accepted code or stated offer, exclusions. Do not include customer or payment data."></textarea></label><label>Checked by<input name="reviewer" required minlength="2" maxlength="100"></label><button>record.check_</button></form></details><details><summary>Verification history</summary><pre>${esc(dashboard.checks.filter(c=>c.offer_id===o.id).map(c=>`${c.checked_at} / ${c.method} / ${c.result}\n${c.evidence}\n${c.source_url}\nChecked by ${c.reviewer}`).join('\n\n')||'No checks yet.')}</pre></details></article>`).join('')||'<p>No offers yet. Start with a draft.</p>';
 document.querySelector('#operator-reports').innerHTML=dashboard.reports.map(r=>`<article class="desk-record"><h3>${esc(r.reason.replaceAll('_',' '))}</h3><span class="data">${esc(r.status)} · ${esc(r.created_at)}</span><p>${esc(r.page_path)}</p><p>${esc(r.details||'No details supplied.')}</p><form class="alert-form review-form" data-report="${esc(r.id)}"><label>Status<select name="status"><option value="reviewing">Reviewing</option><option value="resolved" ${r.status==='resolved'?'selected':''}>Resolved</option><option value="dismissed" ${r.status==='dismissed'?'selected':''}>Dismissed</option></select></label><label>Review note<textarea name="resolution" minlength="5" maxlength="1000" required>${esc(r.resolution||'')}</textarea></label><button>save.review_</button></form></article>`).join('')||'<p>No reports waiting.</p>';
 document.querySelector('#operator-audit').innerHTML=dashboard.audit.map(a=>`<p><span class="data">${esc(a.created_at)}</span> ${esc(a.event)} · ${esc(a.entity||'')}</p>`).join('')||'<p>No publishing activity yet.</p>';}
 async function action(fn){status.textContent='Working…';try{const result=await fn();await refresh();status.textContent=result?.message||'Saved.';}catch(error){status.textContent=error.message;}}
 login.addEventListener('submit',async event=>{event.preventDefault();key=login.querySelector('input').value;login.reset();try{await refresh();login.hidden=true;desk.hidden=false;status.textContent='Desk unlocked.';}catch(error){lock();status.textContent=error.message;}});
 document.querySelector('#lock-desk').addEventListener('click',lock);for(const event of ['pointerdown','keydown'])document.addEventListener(event,()=>{lastActivity=Date.now();},{passive:true});setInterval(()=>{if(key&&Date.now()-lastActivity>15*60*1000)lock();},30000);window.addEventListener('pagehide',lock);
 const offerForm=document.querySelector('#offer-form');offerForm.addEventListener('submit',event=>{event.preventDefault();const data=Object.fromEntries(new FormData(offerForm));data.glitch=offerForm.glitch.checked;data.affiliate=offerForm.affiliate.checked;data.expires_at=new Date(data.expires_at).toISOString();void action(()=>api('offer',data));});
 desk.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;if(b.dataset.edit){const o=dashboard.offers.find(o=>o.id===b.dataset.edit);for(const [field,value] of Object.entries(o)){const input=offerForm.elements.namedItem(field);if(!input)continue;if(input.type==='checkbox')input.checked=value;else if(field==='expires_at'){const date=new Date(value);input.value=new Date(date.getTime()-date.getTimezoneOffset()*60000).toISOString().slice(0,16);}else input.value=value??'';}offerForm.scrollIntoView({behavior:'smooth'});return;}if(b.dataset.publish)void action(()=>api('publish',{id:b.dataset.publish}));if(b.dataset.pause)void action(()=>api('status',{id:b.dataset.pause,status:'paused'}));if(b.dataset.patch)void action(()=>api('status',{id:b.dataset.patch,status:'patched'}));});
 desk.addEventListener('submit',event=>{const form=event.target;if(form.classList.contains('check-form')){event.preventDefault();void action(()=>api('check',{...Object.fromEntries(new FormData(form)),id:form.dataset.offer}));}if(form.classList.contains('review-form')){event.preventDefault();void action(()=>api('report',{...Object.fromEntries(new FormData(form)),id:form.dataset.report}));}});
 document.querySelector('#prepare-alert').addEventListener('click',()=>void action(()=>api('alert-draft',{})));
})();
